def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_gcd(N, A):
    total_gcd = reduce(gcd, A)
    if total_gcd > 1:
        return total_gcd

    max_gcd_value = 1
    for i in range(N):
        current_gcd = reduce(gcd, A[:i] + A[i+1:])
