import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_gcd_after_replacement(N, A):
    total_gcd = reduce(gcd, A)

    if total_gcd > 1:
        return total_gcd

    max_gcd = 0
    for i in range(N):
        remaining_gcd = reduce(gcd, A[:i] + A[i+1:])
        for j in range(1, 10**9 + 1):
            new_gcd = gcd(remaining_gcd, j)
            if new_gcd > max_gcd:
                max_gcd = new_gcd
            if new_gcd == remaining_gcd:
                break

    return max_gcd

